"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * macOS 26 Messages window frame. Measured from `references/macos/captures/conversation-pane-dark.png`
 * (960×640 pt window at 2x):
 * - corners: a circle of radius 27 fits both visible corners to 0.9 px; a continuous corner
 *   (superellipse, exponent 2.6, radius 33) fits to 0.6 px, so browsers with `corner-shape` get that.
 * - dark frame: a 1 pt #4b4b4b rim on the right and bottom edges, a brighter 1 pt highlight along
 *   the top (#6f6f6f over #5d5d5d). The light window shows no rim against white.
 * - traffic lights: Ø12 at (26, 26), (49, 26), (72, 26); gray when the window is not key.
 */
export const macWindowMetrics = {
  width: 960,
  height: 640,
  sidebarWidth: 330,
  cornerRadius: 27,
  trafficLight: { diameter: 12, centers: [26, 49, 72] as const, y: 26 },
};

export type MacWindowProps = Omit<ComponentProps<"div">, "children" | "content"> & {
  width?: number;
  height?: number;
  /** Key window: colored traffic lights and the blue sidebar selection. */
  active?: boolean;
  /** The conversation list. Rendered in the left `sidebarWidth` (330 pt) column. */
  sidebar?: ReactNode;
  sidebarWidth?: number;
  /** The conversation pane. */
  content?: ReactNode;
  children?: ReactNode;
};

const lights = [
  { name: "Close", fill: "#ff5f57", rim: "#e0443e" },
  { name: "Minimize", fill: "#febc2e", rim: "#dea123" },
  { name: "Zoom", fill: "#28c840", rim: "#1aab29" },
];

export function MacWindow({ width = macWindowMetrics.width, height = macWindowMetrics.height, active = true, sidebar, sidebarWidth = macWindowMetrics.sidebarWidth, content, children, className, style, ...props }: MacWindowProps) {
  const { diameter, centers, y } = macWindowMetrics.trafficLight;
  return (
    <div
      data-slot="mac-window"
      data-active={active ? "true" : "false"}
      className={cn("mac-window relative isolate overflow-hidden bg-white text-black [--mac-light-inactive-rim:rgba(0,0,0,0.12)] [--mac-light-inactive:#dcdcdc] dark:bg-[#1e1e1e] dark:text-white dark:[--mac-light-inactive-rim:rgba(255,255,255,0.08)] dark:[--mac-light-inactive:#4f4f4f]", className)}
      style={{ width, height, fontFamily: "-apple-system, BlinkMacSystemFont, sans-serif", WebkitFontSmoothing: "antialiased", ...style }}
      {...props}
    >
      <style>{`
        .mac-window { border-radius: 27px; }
        @supports (corner-shape: superellipse(1.4)) { .mac-window { border-radius: 33px; corner-shape: superellipse(1.4); } }
      `}</style>
      <div data-slot="mac-window-sidebar" className="absolute inset-y-0 left-0" style={{ width: sidebarWidth }}>{sidebar}</div>
      <div data-slot="mac-window-content" className="absolute inset-y-0 right-0" style={{ left: sidebarWidth }}>{content ?? children}</div>
      <div data-slot="traffic-lights" role="group" aria-label="Window controls" className="absolute left-0 top-0 z-20" style={{ height: y * 2, width: centers[2] + diameter }}>
        {lights.map((light, index) => (
          <span
            key={light.name}
            data-slot="traffic-light"
            role="img"
            aria-label={light.name}
            className="absolute rounded-full"
            style={{
              width: diameter, height: diameter, left: centers[index] - diameter / 2, top: y - diameter / 2,
              background: active ? light.fill : "var(--mac-light-inactive)",
              boxShadow: `inset 0 0 0 0.5px ${active ? light.rim : "var(--mac-light-inactive-rim)"}`,
            } as CSSProperties}
          />
        ))}
      </div>
      {/* Frame rim. Dark windows draw a 1 pt light border with a brighter top highlight; light windows draw none against white. */}
      <div aria-hidden="true" data-slot="mac-window-rim" className="mac-window pointer-events-none absolute inset-0 z-30 hidden dark:block" style={{ boxShadow: "inset 0 1px 0 #666666, inset 0 0 0 1px #4b4b4b" }} />
    </div>
  );
}
